/// Distances along [sampleRoute] (m) of two red lights to stop at, for
/// `GpsSimulator(sampleRoute, stops: sampleRouteRedLights)`. They only make
/// sense on [sampleRoute]; a simulator has no red lights by default.
const sampleRouteRedLights = [420.0, 2650.0];

/// Per-segment limits (m/s) from runs of (first segment, km/h).
List<double?> _limitsKmh(List<(int, int?)> runs, int segments) => [
  for (var i = 0; i < segments; i++)
    switch (runs.lastWhere((r) => r.$1 <= i).$2) {
      final kmh? => kmh / 3.6,
      null => null,
    },
];
